<?php
declare(strict_types=1);

/**
 * SOMBA
  * Vérification automatique des paiements Maketou
   *
    * À exécuter régulièrement avec un cron.
     */

     require_once __DIR__ . '/../config/bootstrap.php';
     require_once __DIR__ . '/../api/maketou.php';

     $pdo = db();

     echo "SOMBA payment checker\n";
     echo "Started: " . date('Y-m-d H:i:s') . "\n\n";


     /*
     |--------------------------------------------------------------------------
     | Chercher les commandes en attente
     |--------------------------------------------------------------------------
     */

     $stmt = $pdo->prepare(
         "SELECT *
              FROM orders
                   WHERE payment_provider = 'maketou'
                        AND payment_status IN
                                ('pending', 'waiting_payment')
                                     AND payment_reference IS NOT NULL
                                          ORDER BY created_at ASC
                                               LIMIT 50"
                                               );

                                               $stmt->execute();

                                               $orders = $stmt->fetchAll();

                                               echo "Orders found: " .
                                                   count($orders) .
                                                       "\n\n";


                                                       foreach ($orders as $order) {

                                                           $orderId =
                                                                   (int)$order['id'];

                                                                       $cartId =
                                                                               (string)$order['payment_reference'];

                                                                                   echo "Checking order #{$orderId}\n";
                                                                                       echo "Cart: {$cartId}\n";

                                                                                           try {

                                                                                                   $cart = maketouGetCart(
                                                                                                               $cartId
                                                                                                                       );

                                                                                                                               $status =
                                                                                                                                           (string)(
                                                                                                                                                           $cart['status']
                                                                                                                                                                           ?? ''
                                                                                                                                                                                       );

                                                                                                                                                                                               echo "Maketou status: {$status}\n";


                                                                                                                                                                                                       /*
                                                                                                                                                                                                               |--------------------------------------------------------------------------
                                                                                                                                                                                                                       | PAIEMENT CONFIRMÉ
                                                                                                                                                                                                                               |--------------------------------------------------------------------------
                                                                                                                                                                                                                                       */

                                                                                                                                                                                                                                               if ($status === 'completed') {

                                                                                                                                                                                                                                                           $pdo->beginTransaction();

                                                                                                                                                                                                                                                                       try {

                                                                                                                                                                                                                                                                                       /*
                                                                                                                                                                                                                                                                                                        * Mise à jour atomique.
                                                                                                                                                                                                                                                                                                                         */

                                                                                                                                                                                                                                                                                                                                         $stmt = $pdo->prepare(
                                                                                                                                                                                                                                                                                                                                                             "UPDATE orders
                                                                                                                                                                                                                                                                                                                                                                                  SET
                                                                                                                                                                                                                                                                                                                                                                                                          payment_status = 'paid',
                                                                                                                                                                                                                                                                                                                                                                                                                                  delivery_status = 'pending'
                                                                                                                                                                                                                                                                                                                                                                                                                                                       WHERE id = ?
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            AND payment_status <> 'paid'"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            $stmt->execute([
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                $orderId
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ]);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                /*
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 * Événement.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  */

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  try {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      $eventStmt = $pdo->prepare(
